from .common import ObjDataType


class AccountData(object):
    """账户数据类"""

    def __init__(self, data: ObjDataType = {}) -> None:
        self._investor = data.get("InvestorID", "")
        self._account = data.get("AccountID", "")
        self._balance = data.get("Balance", 0.0)
        self._pre_balance = data.get("PreBalance", 0.0)
        self._available = data.get("Available", 0.0)
        self._pre_available = data.get("PreAvailable", 0.0)
        self._close_profit = data.get("CloseProfit", 0.0)
        self._position_profit = data.get("PositionProfit", 0.0)
        self._dynamic_rights = data.get("DynamicRights", 0.0)
        self._commission = data.get("Fee", 0.0)
        self._margin = data.get("Margin", 0.0)
        self._frozen_margin = data.get("FrozenMargin", 0.0)
        self._deposit = data.get("Deposit", 0.0)
        self._withdraw = data.get("Withdraw", 0.0)

    def __repr__(self) -> str:
        return str(
            {
                "investor": self._investor,
                "account": self._account,
                "balance": self._balance,
                "pre_balance": self._pre_balance,
                "available": self._available,
                "pre_available": self._pre_available,
                "close_profit": self._close_profit,
                "position_profit": self._position_profit,
                "dynamic_rights": self._dynamic_rights,
                "commission": self._commission,
                "margin": self._margin,
                "frozen_margin": self._frozen_margin,
                "deposit": self._deposit,
                "withdraw": self._withdraw,
            }
        )

    @property
    def investor(self) -> str:
        """投资者账号"""
        return self._investor

    @property
    def account(self) -> str:
        """资金账号"""
        return self._account

    @property
    def balance(self) -> float:
        """结算准备金"""
        return self._balance

    @property
    def pre_balance(self) -> float:
        """上次结算准备金"""
        return self._pre_balance

    @property
    def available(self) -> float:
        """可用资金"""
        return self._available

    @property
    def pre_available(self) -> float:
        """上日可用资金"""
        return self._pre_available

    @property
    def close_profit(self) -> float:
        """平仓盈亏"""
        return self._close_profit

    @property
    def position_profit(self) -> float:
        """持仓盈亏"""
        return self._position_profit

    @property
    def dynamic_rights(self) -> float:
        """动态权益"""
        return self._dynamic_rights

    @property
    def commission(self) -> float:
        """手续费"""
        return self._commission

    @property
    def margin(self) -> float:
        """占用保证金"""
        return self._margin

    @property
    def frozen_margin(self) -> float:
        """冻结保证金"""
        return self._frozen_margin

    @property
    def risk(self) -> float:
        """风险度"""
        return self._margin / self._dynamic_rights

    @property
    def deposit(self) -> float:
        """入金金额"""
        return self._deposit

    @property
    def withdraw(self) -> float:
        """出金金额"""
        return self._withdraw

from pythongo.const import OPTION_MAP, PRODUCT_MAP

from .common import ObjDataType


class InstrumentData(object):
    """合约数据类"""

    def __init__(self, data: ObjDataType = {}) -> None:
        self._exchange = data.get("Exchange", "")
        self._instrument_id = data.get("InstrumentID", "")
        self._instrument_name = data.get("InstrumentName", "")
        self._product_id = data.get("ProductID", "")
        self._product_type = data.get("ProductClass", "")
        self._price_tick = data.get("PriceTick", 0.0)
        self._size = data.get("VolumeMultiple", 0)
        self._strike_price = data.get("StrikePrice", 0.0)
        self._underlying_symbol = data.get("UnderlyingInstrID", "")
        self._options_type = data.get("OptionsType", "")
        self._expire_date = data.get("ExpireDate", "")
        self._min_limit_order_size = data.get("MinLimitOrderVolume", 0)
        self._max_limit_order_size = data.get("MaxLimitOrderVolume", 0)
        self._lower_limit_price = data.get("LowerLimitPrice", 0.0)
        self._upper_limit_price = data.get("UpperLimitPrice", 0.0)

    def __repr__(self) -> str:
        return str(
            {
                "exchange": self._exchange,
                "instrument_id": self._instrument_id,
                "instrument_name": self._instrument_name,
                "product_id": self._product_id,
                "product_type": self.product_type,
                "price_tick": self._price_tick,
                "size": self._size,
                "strike_price": self._strike_price,
                "underlying_symbol": self._underlying_symbol,
                "options_type": self.options_type,
                "expire_date": self._expire_date,
                "min_limit_order_size": self._min_limit_order_size,
                "max_limit_order_size": self._max_limit_order_size,
                "lower_limit_price": self._lower_limit_price,
                "upper_limit_price": self._upper_limit_price,
            }
        )

    @property
    def exchange(self) -> str:
        """交易所代码"""
        return self._exchange

    @property
    def instrument_id(self) -> str:
        """合约代码"""
        return self._instrument_id

    @property
    def instrument_name(self) -> str:
        """合约中文名"""
        return self._instrument_name

    @property
    def product_id(self) -> str:
        """品种代码"""
        return self._product_id

    @property
    def product_type(self) -> str:
        """品种类型"""
        return PRODUCT_MAP.get(self._product_type, "")

    @property
    def price_tick(self) -> float:
        """最小变动价位"""
        return self._price_tick

    @property
    def size(self) -> int:
        """合约大小（合约乘数）"""
        return self._size

    @property
    def strike_price(self) -> float:
        """期权行权价"""
        return self._strike_price

    @property
    def underlying_symbol(self) -> str:
        """标的物代码"""
        return self._underlying_symbol

    @property
    def options_type(self) -> str:
        """期权类型"""
        return OPTION_MAP.get(self._options_type, "")

    @property
    def expire_date(self) -> str:
        """合约到期日"""
        return self._expire_date

    @property
    def min_limit_order_size(self) -> int:
        """最小下单量"""
        return self._min_limit_order_size

    @property
